WITH remaining_keys AS (SELECT page, event_type FROM web_events EXCEPT ALL SELECT page, event_type FROM web_events WHERE session_id IN (22, 26)), reconciled AS (SELECT s.* FROM web_events s JOIN remaining_keys k ON s.page = k.page AND s.event_type = k.event_type) SELECT CASE WHEN duration_sec >= 477 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, session_id, DATE_TRUNC('QUARTER', event_time) AS quarter_start, AVG(duration_sec) AS avg_duration_sec, COUNT(*) AS cnt, SIZE(COLLECT_SET(page)) AS num_pages, PERCENTILE_APPROX(duration_sec, 0.95) AS duration_sec_p95, SUM(CASE WHEN event_type = 'purchase' THEN duration_sec ELSE 0 END) AS purchase_duration_sec, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, PERCENT_RANK() OVER (PARTITION BY CASE WHEN duration_sec >= 477 THEN 'LARGE' ELSE 'SMALL' END ORDER BY (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 DESC) AS duration_min_percent_rank FROM reconciled GROUP BY 1, 2, 3 HAVING SIZE(COLLECT_SET(page)) > 1;
